const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hoodCanal = ee.Geometry.Polygon([
    [-123.0, 47.8],
    [-122.6, 47.8], 
    [-122.6, 47.2],
    [-123.0, 47.2],
    [-123.0, 47.8]
  ]);

  // Time periods: late Aug 2022 vs full Aug 2021
  const start2022 = '2022-08-20';
  const end2022 = '2022-08-31';
  const start2021 = '2021-08-01';
  const end2021 = '2021-08-31';

  // 2. Data Acquisition - Sentinel-2 for blue band analysis
  function getSentinel2Collection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(hoodCanal)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
      .map(function(image) {
        // Cloud masking using QA60 band
        var qa = image.select('QA60');
        var cloudBitMask = 1 << 10;
        var cirrusBitMask = 1 << 11;
        var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                  .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).select(['B2']); // Blue band
      });
  }

  const col2022 = getSentinel2Collection(start2022, end2022);
  const col2021 = getSentinel2Collection(start2021, end2021);

  // Check collection sizes
  const size2022 = col2022.size().getInfo();
  const size2021 = col2021.size().getInfo();

  console.log(`2022 Images: ${size2022}, 2021 Images: ${size2021}`);

  if (size2022 === 0 || size2021 === 0) {
    console.log("C1");
    return;
  }

  // Create median composites
  const comp2022 = col2022.median();
  const comp2021 = col2021.median();

  // Calculate mean blue reflectance and pixel counts
  function getStats(image, year) {
    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: hoodCanal,
      scale: 100,
      maxPixels: 1e9
    });

    const mean = stats.get('B2').getInfo();
    const count = stats.get('B2_count').getInfo();

    console.log(`${year} Mean Blue: ${mean ? mean.toFixed(4) : 'null'}, Pixels: ${count}`);
    return {mean: mean, count: count};
  }

  const stats2022 = getStats(comp2022, "2022");
  const stats2021 = getStats(comp2021, "2021");

  // Check for valid pixels
  if (stats2022.count === 0 || stats2021.count === 0) {
    console.log("C2");
    return;
  }

  // Check for calculation failures
  if (stats2022.mean === null || stats2021.mean === null || 
      isNaN(stats2022.mean) || isNaN(stats2021.mean)) {
    console.log("C3");
    return;
  }

  // Compare blue reflectance - if 2022 is at least 10% higher than 2021
  const diff = ((stats2022.mean - stats2021.mean) / stats2021.mean) * 100;
  console.log(`Blue reflectance difference: ${diff.toFixed(1)}%`);

  if (diff > 10) { // 10% threshold for "noticeable" difference
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
